	#[test]
	fn stale_and_future_versions_are_distinguishable() {
		let error = VaultState::try_from_bytes(&envelope(1 as u8)).err().expect("a future envelope must fail");
		assert_eq!(error, VaultStateVersionError::Future { stored: 1 });
		assert_eq!(VaultStateVersionError::Future { stored: 1 }.to_string(), "migration version mismatch: expected 0, received 1 (the data was written by a newer program; upgrade this client)");
		assert!(
			VaultState::try_from_bytes(&envelope(0 as u8)).is_ok(),
			"the current version must decode",
		);
	}
